using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpHttpServer;

[McpServerResource(Name = "config://app",
    Description = "Returns application configuration data",
    MimeType = "application/json")]
public class ConfigResource
{
    private static readonly Dictionary<string, object> AppConfig = new()
    {
        ["appName"] = "McpHttpServer",
        ["version"] = "1.0.0",
        ["environment"] = "production",
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false
        }
    };

    [ResourceTemplate("config://app")]
    [Description("Returns the full application configuration")]
    public static string GetAppConfig()
    {
        return JsonSerializer.Serialize(AppConfig, new JsonSerializerOptions { WriteIndented = true });
    }

    [ResourceTemplate("config://app/{section}")]
    [Description("Returns a specific configuration section")]
    public static string GetConfigSection(string section)
    {
        if (AppConfig.TryGetValue(section, out var value))
        {
            return JsonSerializer.Serialize(value, new JsonSerializerOptions { WriteIndented = true });
        }

        return JsonSerializer.Serialize(new { error = $"Section '{section}' not found" });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public class EchoTool
{
    [McpServerTool(Name = "echo"), Description("Echoes the input message back")]
    public static string Echo([Description("The message to echo")] string message)
    {
        return $"Echo: {message}";
    }

    [McpServerTool(Name = "get_time"), Description("Returns the current server time")]
    public static string GetTime()
    {
        return DateTime.UtcNow.ToString("o");
    }
}

